          a.download = (document.title || "noobtrader-report").replace(/[^a-z0-9]+/gi, "-").toLowerCase() + ".png";
          document.body.appendChild(a); a.click(); document.body.removeChild(a);
          URL.revokeObjectURL(a.href);
